; ?>privacy/">プライバシーポリシー</a><a class="Footer_link__16ENv" href="<?php echo esc_url( home_url( '/' ) ); ?>sitemap/">サイトマップ</a></div></div></div></div><p class="Footer_copyright__8W_Zp">© NOAH CONSTRUCTION CO.,LTD. All Rights Reserved.</p></footer><?php wp_footer(); ?></body></html>